option.value:
@echo off echo Starting Product Management Interface... echo.
cd /d "%~dp0"
echo Running: tn.formini.product.launchers.ProduitManagementLauncher java -cp "src/main/java" tn.formini.product.launchers.ProduitManagementLauncher
if errorlevel 1 ( echo. echo Error occurred while running the application. echo Make sure Java is properly installed and configured. echo. pause )

Write-Host "Starting Product Management Interface..." -ForegroundColor Green
Write-Host ""

Set-Location $PSScriptRoot

Write-Host "Running: tn.formini.product.launchers.ProduitManagementLauncher" -ForegroundColor Yellow
try {
    java -cp "src/main/java" tn.formini.product.launchers.ProduitManagementLauncher
} catch {
    Write-Host "Error occurred while running the application." -ForegroundColor Red
    Write-Host "Make sure Java is properly installed and configured." -ForegroundColor Red
    Write-Host ""
    Write-Host "Press any key to continue..." -ForegroundColor Yellow
    $null = $Host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")
}

Write-Host "Starting Product Management Interface (via Maven javafx:run)..." -ForegroundColor Green
Write-Host ""

Set-Location $PSScriptRoot

Write-Host "Running via Maven plugin: javafx:run" -ForegroundColor Yellow
try {
    mvn javafx:run
} catch {
    Write-Host "Error occurred while running 'mvn javafx:run'." -ForegroundColor Red
    Write-Host "Make sure Maven is installed and in PATH, and JavaFX dependencies are available." -ForegroundColor Red
    Write-Host "If you prefer to run the packaged jar, use: java --module-path <javafx-sdk-lib> --add-modules=javafx.controls,javafx.fxml,javafx.web -jar target\yourapp.jar" -ForegroundColor Yellow
    Write-Host "Press any key to continue..." -ForegroundColor Yellow
    $null = $Host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")
}
